INSERT INTO collection_pages VALUES('854bcd9df832c41998515e12e663b11595f382ef36ffd0212d52f720fc2cda8b','83bde7e41f2e78c281446a7096ede0957f918e759493ff6534c6159b44e0fd6f','{"hasNext":false,"items":[{"author":{"account":{"login":"pmaravelias-corero","providerType":"User"},"email":"periklis.maravelias@corero.com","name":"Periklis Maravelias"},"authoredDate":"2026-06-23T16:18:09Z","committedDate":"2026-08-25T16:11:56Z","committer":{"account":{"login":"pmaravelias-corero","providerType":"User"},"email":"periklis.maravelias@corero.com","name":"Periklis Maravelias"},"observedAt":"2026-10-08T23:29:32.821Z","repositoryId":1278267277,"sha":"b196576ead027c3cf7cb1d9ff5e99054f36231bc"}],"observedAt":"2026-10-08T23:29:32.821Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/230241189?v=4","events_url":"https://api.github.com/users/pmaravelias-corero/events{/privacy}","followers_url":"https://api.github.com/users/pmaravelias-corero/followers","following_url":"https://api.github.com/users/pmaravelias-corero/following{/other_user}","gists_url":"https://api.github.com/users/pmaravelias-corero/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/pmaravelias-corero","id":230241189,"login":"pmaravelias-corero","node_id":"U_kgDODbkzpQ","organizations_url":"https://api.github.com/users/pmaravelias-corero/orgs","received_events_url":"https://api.github.com/users/pmaravelias-corero/received_events","repos_url":"https://api.github.com/users/pmaravelias-corero/repos","site_admin":false,"starred_url":"https://api.github.com/users/pmaravelias-corero/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/pmaravelias-corero/subscriptions","type":"User","url":"https://api.github.com/users/pmaravelias-corero","user_view_type":"public"},"comments_url":"https://api.github.com/repos/pmaravelias-corero/core-scripts/commits/b196576ead027c3cf7cb1d9ff5e99054f36231bc/comments","commit":{"author":{"date":"2026-06-23T16:18:09Z","email":"periklis.maravelias@corero.com","name":"Periklis Maravelias"},"comment_count":0,"committer":{"date":"2026-08-25T16:11:56Z","email":"periklis.maravelias@corero.com","name":"Periklis Maravelias"},"message":"Add core-scripts dev tooling\n\nIncludes four tools for the CORE microservices workspace:\n\n- core-local-deploy: start/teardown/redeploy a CORElet locally (Docker\n  Compose + UI/API dev servers). Supports terminal emulator detection\n  (kitty, wezterm, gnome-terminal, macOS), extra-service auto-detection,\n  background process health checks, and tab-completion for bash/zsh.\n\n- core-sync-projects: batch-sync all CORElet repos to their remote\n  default branch. Handles dirty working trees interactively (continue /\n  stash-and-reapply / abort), prunes remote-tracking refs, merged\n  branches, and gone-upstream branches. Supports --status mode.\n\n- core-mcp: read-only MCP server that gives Claude Code ambient\n  knowledge of the workspace (list_corelets, get_corelet_info,\n  get_module_federation_graph, get_api_routes, get_docker_stack,\n  resolve_api_route, get_workspace_overview, find_usages,\n  get_dependency_graph). Parses docker-compose, env files, MF configs,\n  and Micronaut @Controller sources without external YAML/AST libraries.\n\n- core-dev-hub: single-page tabbed browser dashboard (no build step)\n  that calls the GitHub API to show PRs pending review, your open PRs,\n  and Dependabot bumps across all CORE repos. Tab logic is split into\n  tabs/<name>.js files; new tabs register via registerTab(). GitHub\n  token is stored in localStorage, never in source. Includes a Windows\n  Desktop shortcut for access outside WSL.","tree":{"sha":"6276d4a89b785993ddc466affb567459b6ac901f","url":"https://api.github.com/repos/pmaravelias-corero/core-scripts/git/trees/6276d4a89b785993ddc466affb567459b6ac901f"},"url":"https://api.github.com/repos/pmaravelias-corero/core-scripts/git/commits/b196576ead027c3cf7cb1d9ff5e99054f36231bc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/230241189?v=4","events_url":"https://api.github.com/users/pmaravelias-corero/events{/privacy}","followers_url":"https://api.github.com/users/pmaravelias-corero/followers","following_url":"https://api.github.com/users/pmaravelias-corero/following{/other_user}","gists_url":"https://api.github.com/users/pmaravelias-corero/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/pmaravelias-corero","id":230241189,"login":"pmaravelias-corero","node_id":"U_kgDODbkzpQ","organizations_url":"https://api.github.com/users/pmaravelias-corero/orgs","received_events_url":"https://api.github.com/users/pmaravelias-corero/received_events","repos_url":"https://api.github.com/users/pmaravelias-corero/repos","site_admin":false,"starred_url":"https://api.github.com/users/pmaravelias-corero/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/pmaravelias-corero/subscriptions","type":"User","url":"https://api.github.com/users/pmaravelias-corero","user_view_type":"public"},"html_url":"https://github.com/pmaravelias-corero/core-scripts/commit/b196576ead027c3cf7cb1d9ff5e99054f36231bc","node_id":"C_kwDOTDDPjdoAKGIxOTY1NzZlYWQwMjdjM2NmN2NiMWQ5ZmY1ZTk5MDU0ZjM2MjMxYmM","parents":[],"sha":"b196576ead027c3cf7cb1d9ff5e99054f36231bc","url":"https://api.github.com/repos/pmaravelias-corero/core-scripts/commits/b196576ead027c3cf7cb1d9ff5e99054f36231bc"}],"requestUrl":"https://api.github.com/repos/pmaravelias-corero/core-scripts/commits?per_page=100&page=1&sha=b196576ead027c3cf7cb1d9ff5e99054f36231bc&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A18%3A55.105Z"}');
